function.arguments:
{"command":"runuser -u appsvc -- bash -c '
  ok=1
  test -r /etc/appsvc/config.yaml && echo "read config.yaml: OK" || { echo "read config.yaml: FAIL"; ok=0; }
  for f in db_password api_token signing.key; do
    if head -c1 /etc/appsvc/secrets/$f >/dev/null 2>&1; then echo "read secret $f: OK"; else echo "read secret $f: FAIL"; ok=0; fi
  done
  test -w /var/lib/appsvc/data && echo "write data dir: OK" || { echo "write data dir: FAIL"; ok=0; }
  test -w /var/lib/appsvc/run  && echo "write run dir: OK"  || { echo "write run dir: FAIL"; ok=0; }
  exit $((1-ok))
' && echo "== service account has everything it needs =="
echo "--- and a non-privileged outsider is still locked out (expected to FAIL) ---"
runuser -u nobody -- cat /etc/appsvc/secrets/db_password 2>&1 | tail -1 || true"}
